Translate the following MS C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#define _USE_MATH_DEFINES

#include <cmath>
#include <cstdio>
#include <deque>
#include <algorithm>
#include <functional>
#include <iostream>
#include <iterator>
#include <list>
#include <map>
#include <queue>
#include <set>
#include <stack>
#include <string>
#include <vector>

#define mp make_pair
#define pb push_back

char A[12][12];
char B[12][12];
int n, t;
bool _dp[70][12][12][12][12];
bool dp[12][12][12][12];
int tim[12][12];

struct State {
    int tt, x, y, x0, y0;
};

void setdp_iter(int sx, int sy) {
    if (t >= 70) return;
    if (A[sx][sy] < '0' || A[sx][sy] > '9') return;
    std::stack<State> st;
    st.push({0, sx, sy, sx, sy});
    while (!st.empty()) {
        State cur = st.top(); st.pop();
        int tt = cur.tt, x = cur.x, y = cur.y, x0 = cur.x0, y0 = cur.y0;
        if (x < 0 || x >= n || y < 0 || y >= n) continue;
        if (A[x][y] < '0' || A[x][y] > '9') continue;
        if (tt > t+1) continue;
        if (_dp[tt][x][y][x0][y0]) continue;
        if (tt > tim[x][y] && tim[x][y] != 0) continue;
        if (tt == tim[x][y] && tim[x][y] != 0 && (B[x][y] > '9' || B[x][y] <= '0')) continue;
        _dp[tt][x][y][x0][y0] = true;
        if (tt < tim[x][y]) {
            // push successors in reverse order to mimic recursion order
            st.push({tt+1, x, y-1, x0, y0});
            st.push({tt+1, x, y+1, x0, y0});
            st.push({tt+1, x-1, y, x0, y0});
            st.push({tt+1, x+1, y, x0, y0});
            st.push({tt+1, x, y, x0, y0});
        }
    }
}

int main() {
#ifndef ONLINE_JUDGE
    freopen( "1.txt", "rt", stdin );
#endif

    std::cin >> n >> t;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            std::cin >> A[i][j];

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            std::cin >> B[i][j];

    // BFS using array queue
    std::pair<int,int> q[144];
    int qh = 0, qt = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            tim[i][j] = -1;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (A[i][j] == 'Z') {
                tim[i][j] = 0;
                q[qt++] = mp(i,j);
            }
    int di[] = {-1, 0, 1, 0};
    int dj[] = {0, -1, 0, 1};
    while (qh < qt) {
        std::pair<int,int> p = q[qh++];
        if (tim[p.first][p.second] >= t) continue;
        for (int d = 0; d < 4; d++) {
            int ni = p.first + di[d];
            int nj = p.second + dj[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n &&
                A[ni][nj] >= '0' && A[ni][nj] <= '9' && tim[ni][nj] == -1) {
                tim[ni][nj] = tim[p.first][p.second] + 1;
                q[qt++] = mp(ni,nj);
            }
        }
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (tim[i][j] == -1)
                tim[i][j] = t;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (A[i][j] >= '0' && A[i][j] <= '9')
                setdp_iter(i, j);

    std::vector<std::vector<int> > G;
    int F[210][210];
    int E[210], H[210];
    int C[210][210];
    int pN[11][11];
    std::vector<int> st;
    G.pb(st);

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            for (int i2 = 0; i2 < n; i2++)
                for (int j2 = 0; j2 < n; j2++)
                    for (int nt = 0; nt <= t; nt++)
                        dp[i1][j1][i2][j2] |= _dp[nt][i1][j1][i2][j2];

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            if (A[i1][j1] > '0' && A[i1][j1] <= '9') {
                int k = G.size();
                std::vector<int> g;
                G.push_back(g);
                E[k] = A[i1][j1] - '0';
                for (int i2 = 0; i2 < n; i2++)
                    for (int j2 = 0; j2 < n; j2++)
                        if (B[i2][j2] > '0' && B[i2][j2] <= '9')
                        if (dp[i2][j2][i1][j1]) {
                            int _k;
                            if (pN[i2][j2] == 0) {
                                std::vector<int> _g;
                                _k = G.size();
                                G.push_back(_g);
                                pN[i2][j2] = _k;
                            } else {
                                _k = pN[i2][j2];
                            }
                            G[k].pb(_k);
                            G[_k].pb(k);
                            C[k][_k] = 10000;
                            C[_k][k] = 0;
                        }
            }

    for (int i2 = 0; i2 < n; i2++)
        for (int j2 = 0; j2 < n; j2++)
            if (B[i2][j2] > '0' && B[i2][j2] <= '9' && pN[i2][j2] > 0) {
                int _k = pN[i2][j2];
                G[_k].push_back(0);
                C[_k][0] = B[i2][j2] - '0';
                C[0][_k] = 0;
            }

    // Push-relabel (same as variant 1)
    while (true) {
        bool ff = true;
        for (int i = 1; i < (int)G.size(); i++) {
            while (E[i] > 0) {
                bool f = true;
                int minH = 10000;
                for (int _j = 0; _j < (int)G[i].size(); _j++) {
                    int j = G[i][_j];
                    if (C[i][j] - F[i][j]) minH = std::min(minH, H[j]);
                    if (C[i][j] - F[i][j] > 0 && H[i] == H[j] + 1) {
                        int d = std::min(C[i][j] - F[i][j], E[i]);
                        F[i][j] += d;
                        F[j][i] -= d;
                        E[i] -= d;
                        E[j] += d;
                        f = false;
                        ff = false;
                        if (E[i] == 0) break;
                    }
                }
                if (E[i] == 0) break;
                if (H[i] != minH + 1 && minH != 10000) {
                    f = false;
                    ff = false;
                    H[i] = minH + 1;
                }
                if (f) break;
            }
        }
        if (ff) break;
    }

    std::cout << E[0];
    return 0;
}
